A_{im}x_{m}+b_i+C_{ikq}x_{k}y_{q}
                               & \not\Rightarrow
                                A_{im}x_{m}+b_i+C_{iqq}x_{q}y_{q}\quad (\text{conflict with dummy index}) \\
A_{im}x_{m}+b_i+C_{ikq}x_{k}y_{q}
                                &\not \Rightarrow
                                 A_{ii}x_{i}+b_i+C_{ikq}x_{k}y_{q}\quad (\text{conflict with free index}) \\
\end{align}
\]
